// Unicode display width calculation.

include!("width_table.rs");

/// Compute the display width of a single Unicode scalar value.
pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    // ASCII fast path
    if cp < 0x80 {
        return 1;
    }
    // Binary search in zero-width ranges
    if in_ranges(cp, ZERO_WIDTH) {
        return 0;
    }
    if in_ranges(cp, WIDE_WIDTH) {
        return 2;
    }
    1
}

fn in_ranges(cp: u32, table: &[(u32, u32)]) -> bool {
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (s, e) = table[mid];
        if cp < s {
            hi = mid;
        } else if cp > e {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

/// Compute display width of a string (sum of character widths).
pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}
