// Simple CSV parser.

use std::io::{self, Read};

/// Errors while reading CSV.
#[derive(Debug)]
pub enum CsvError {
    Io(io::Error),
    Utf8 { record: u64, line: u64, field: u64, byte: u64 },
    BadRecord { record: u64, line: u64, byte: u64, got: usize, want: usize },
}

impl std::fmt::Display for CsvError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CsvError::Io(e) => {
                // Try to produce the original message similar to rust stdlib
                write!(f, "{} (os error {})", e, e.raw_os_error().unwrap_or(0))
            }
            CsvError::Utf8 { record, line, field, byte } => write!(
                f,
                "CSV parse error: record {} (line {}, field: {}, byte: {}): invalid utf-8: invalid UTF-8 in field {} near byte index 0",
                record, line, field, byte, field
            ),
            CsvError::BadRecord { record, line, byte, got, want } => write!(
                f,
                "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                record, line, byte, got, want
            ),
        }
    }
}

pub struct CsvReader<R: Read> {
    reader: R,
    buf: Vec<u8>,
    buf_pos: usize,
    buf_end: usize,
    eof: bool,
    delimiter: u8,
    // counters for error reporting
    pub byte_pos: u64,
    pub line: u64,
}

impl<R: Read> CsvReader<R> {
    pub fn new(reader: R, delimiter: u8) -> Self {
        CsvReader {
            reader,
            buf: vec![0u8; 8192],
            buf_pos: 0,
            buf_end: 0,
            eof: false,
            delimiter,
            byte_pos: 0,
            line: 1,
        }
    }

    fn fill(&mut self) -> io::Result<()> {
        if self.buf_pos < self.buf_end || self.eof {
            return Ok(());
        }
        self.buf_pos = 0;
        self.buf_end = self.reader.read(&mut self.buf)?;
        if self.buf_end == 0 {
            self.eof = true;
        }
        Ok(())
    }

    fn peek(&mut self) -> io::Result<Option<u8>> {
        self.fill()?;
        if self.buf_pos < self.buf_end {
            Ok(Some(self.buf[self.buf_pos]))
        } else {
            Ok(None)
        }
    }

    fn advance(&mut self) {
        self.buf_pos += 1;
        self.byte_pos += 1;
    }

    /// Read the next record. Returns None on EOF.
    /// Each field is returned as raw bytes.
    pub fn next_record(&mut self) -> Result<Option<Vec<Vec<u8>>>, CsvError> {
        // Check eof
        if self.peek().map_err(CsvError::Io)?.is_none() {
            return Ok(None);
        }
        let mut record: Vec<Vec<u8>> = Vec::new();
        let mut field: Vec<u8> = Vec::new();
        let mut record_start_byte = self.byte_pos;
        let _ = record_start_byte;

        loop {
            // State: start of a field
            let first = match self.peek().map_err(CsvError::Io)? {
                Some(b) => b,
                None => {
                    // EOF at start of field — still add the (empty) field to record
                    record.push(std::mem::take(&mut field));
                    return Ok(Some(record));
                }
            };

            if first == b'"' {
                // Quoted field
                self.advance();
                loop {
                    match self.peek().map_err(CsvError::Io)? {
                        None => {
                            // End of file inside quoted field — accept what we have.
                            record.push(std::mem::take(&mut field));
                            return Ok(Some(record));
                        }
                        Some(b'"') => {
                            // consume
                            self.advance();
                            match self.peek().map_err(CsvError::Io)? {
                                Some(b'"') => {
                                    field.push(b'"');
                                    self.advance();
                                }
                                _ => {
                                    break;
                                }
                            }
                        }
                        Some(b'\n') => {
                            self.line += 1;
                            field.push(b'\n');
                            self.advance();
                        }
                        Some(b'\r') => {
                            // CRLF treated as LF inside quoted fields? Actually treat as literal \n
                            self.advance();
                            if let Some(b'\n') = self.peek().map_err(CsvError::Io)? {
                                self.advance();
                            }
                            self.line += 1;
                            field.push(b'\n');
                        }
                        Some(b) => {
                            field.push(b);
                            self.advance();
                        }
                    }
                }
                // After close-quote: continue reading until delimiter or newline (appending literal bytes)
                loop {
                    match self.peek().map_err(CsvError::Io)? {
                        None => {
                            record.push(std::mem::take(&mut field));
                            return Ok(Some(record));
                        }
                        Some(b) if b == self.delimiter => {
                            self.advance();
                            record.push(std::mem::take(&mut field));
                            break;
                        }
                        Some(b'\n') => {
                            self.advance();
                            self.line += 1;
                            record.push(std::mem::take(&mut field));
                            return Ok(Some(record));
                        }
                        Some(b'\r') => {
                            self.advance();
                            if let Some(b'\n') = self.peek().map_err(CsvError::Io)? {
                                self.advance();
                            }
                            self.line += 1;
                            record.push(std::mem::take(&mut field));
                            return Ok(Some(record));
                        }
                        Some(b) => {
                            field.push(b);
                            self.advance();
                        }
                    }
                }
            } else {
                // Unquoted field
                loop {
                    match self.peek().map_err(CsvError::Io)? {
                        None => {
                            record.push(std::mem::take(&mut field));
                            return Ok(Some(record));
                        }
                        Some(b) if b == self.delimiter => {
                            self.advance();
                            record.push(std::mem::take(&mut field));
                            break;
                        }
                        Some(b'\n') => {
                            self.advance();
                            self.line += 1;
                            record.push(std::mem::take(&mut field));
                            return Ok(Some(record));
                        }
                        Some(b'\r') => {
                            self.advance();
                            if let Some(b'\n') = self.peek().map_err(CsvError::Io)? {
                                self.advance();
                            }
                            self.line += 1;
                            record.push(std::mem::take(&mut field));
                            return Ok(Some(record));
                        }
                        Some(b) => {
                            field.push(b);
                            self.advance();
                        }
                    }
                }
            }
        }
    }
}
