// Table rendering.

use std::io::{self, Write};
use crate::style::{BorderLine, Style, StyleDef, get_style};
use crate::width::{char_width, str_width};

#[derive(Clone, Copy, PartialEq)]
pub enum Align {
    Left,
    Center,
    Right,
}

impl Align {
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "left" => Some(Align::Left),
            "center" => Some(Align::Center),
            "right" => Some(Align::Right),
            _ => None,
        }
    }
}

pub struct TableOptions {
    pub style: Style,
    pub padding: usize,
    pub indent: usize,
    pub header_align: Align,
    pub body_align: Align,
    pub has_header: bool,
    pub sniff_limit: usize,   // 0 means no limit
    pub number: bool,          // --number option
}

pub struct Table {
    pub header: Option<Vec<String>>,
    pub rows: Vec<Vec<String>>,
    pub opts: TableOptions,
}

impl Table {
    /// Compute column widths using the sniff window.
    fn column_widths(&self) -> Vec<usize> {
        // Determine ncols
        let mut ncols = 0usize;
        if let Some(h) = &self.header {
            ncols = ncols.max(h.len());
        }
        for r in &self.rows {
            ncols = ncols.max(r.len());
        }
        let mut widths = vec![0usize; ncols];

        let limit = if self.opts.sniff_limit == 0 {
            self.rows.len()
        } else {
            self.opts.sniff_limit.min(self.rows.len())
        };

        if let Some(h) = &self.header {
            for (i, v) in h.iter().enumerate() {
                widths[i] = widths[i].max(cell_display_width(v));
            }
        }
        for r in self.rows.iter().take(limit) {
            for (i, v) in r.iter().enumerate() {
                widths[i] = widths[i].max(cell_display_width(v));
            }
        }
        widths
    }

    pub fn render<W: Write>(&self, out: &mut W) -> io::Result<()> {
        let style_def = get_style(self.opts.style);
        let widths = self.column_widths();

        // If there are zero columns, render minimal table
        let mut widths = widths;
        if widths.is_empty() {
            widths = vec![]; // Empty: only borders with no cells
        }

        // Write top border
        if let Some(tl) = &style_def.top {
            write_border(out, &widths, self.opts.padding, self.opts.indent, tl)?;
        }

        let mut num_counter: u64 = 1;

        // Write header row(s)
        let mut first_body = true;

        if let Some(header) = &self.header {
            // number column: if number is enabled, prepend '#' or ' '
            write_data_row(
                out,
                &widths,
                self.opts.padding,
                self.opts.indent,
                &style_def.row,
                header,
                self.opts.header_align,
            )?;
            if let Some(sep) = &style_def.header_sep {
                write_border(out, &widths, self.opts.padding, self.opts.indent, sep)?;
            }
        }

        for (i, row) in self.rows.iter().enumerate() {
            if !first_body {
                if let Some(sep) = &style_def.body_sep {
                    write_border(out, &widths, self.opts.padding, self.opts.indent, sep)?;
                }
            }
            first_body = false;
            let _ = i;
            write_data_row(
                out,
                &widths,
                self.opts.padding,
                self.opts.indent,
                &style_def.row,
                row,
                self.opts.body_align,
            )?;
            num_counter += 1;
        }
        let _ = num_counter;

        // Bottom border
        if let Some(bl) = &style_def.bottom {
            write_border(out, &widths, self.opts.padding, self.opts.indent, bl)?;
        }
        Ok(())
    }
}

/// Width for a cell when sniffing: if cell contains newline, take max over lines.
fn cell_display_width(s: &str) -> usize {
    if s.contains('\n') {
        s.lines().map(str_width).max().unwrap_or(0)
    } else {
        str_width(s)
    }
}

fn write_border<W: Write>(
    out: &mut W,
    widths: &[usize],
    padding: usize,
    indent: usize,
    line: &BorderLine,
) -> io::Result<()> {
    for _ in 0..indent {
        out.write_all(b" ")?;
    }
    out.write_all(line.left.as_bytes())?;
    for (i, &w) in widths.iter().enumerate() {
        if i > 0 {
            out.write_all(line.junction.as_bytes())?;
        }
        let n = w + padding * 2;
        for _ in 0..n {
            out.write_all(line.fill.as_bytes())?;
        }
    }
    out.write_all(line.right.as_bytes())?;
    out.write_all(b"\n")?;
    Ok(())
}

fn write_data_row<W: Write>(
    out: &mut W,
    widths: &[usize],
    padding: usize,
    indent: usize,
    row_style: &BorderLine,
    cells: &[String],
    align: Align,
) -> io::Result<()> {
    // If any cell contains newline, split into subrows
    let mut subrow_counts = 1usize;
    let mut cell_lines: Vec<Vec<&str>> = Vec::with_capacity(widths.len());
    for i in 0..widths.len() {
        if i < cells.len() {
            let c = &cells[i];
            if c.contains('\n') {
                let lines: Vec<&str> = c.split('\n').collect();
                subrow_counts = subrow_counts.max(lines.len());
                cell_lines.push(lines);
            } else {
                cell_lines.push(vec![c.as_str()]);
            }
        } else {
            cell_lines.push(vec![""]);
        }
    }

    for sub in 0..subrow_counts {
        for _ in 0..indent {
            out.write_all(b" ")?;
        }
        out.write_all(row_style.left.as_bytes())?;
        for (i, &w) in widths.iter().enumerate() {
            if i > 0 {
                out.write_all(row_style.junction.as_bytes())?;
            }
            let pad_ch = row_style.fill;
            let cell_str = cell_lines[i].get(sub).copied().unwrap_or("");
            // Write left padding
            for _ in 0..padding {
                out.write_all(pad_ch.as_bytes())?;
            }
            // Write content aligned to width w
            write_aligned(out, cell_str, w, align, pad_ch)?;
            // Write right padding
            for _ in 0..padding {
                out.write_all(pad_ch.as_bytes())?;
            }
        }
        out.write_all(row_style.right.as_bytes())?;
        out.write_all(b"\n")?;
        // For multi-line, only first subrow gets the row border (others use same?)
        // Actually csview shows the raw text with its newlines preserved.
        break; // Actually csview doesn't expand multi-line cells; it just writes the literal string
    }
    Ok(())
}

/// Write a string right-padded to `total_width` columns, taking alignment.
fn write_aligned<W: Write>(
    out: &mut W,
    s: &str,
    total_width: usize,
    align: Align,
    fill: &str,
) -> io::Result<()> {
    // Truncate string to fit total_width if too wide
    let sw = str_width(s);
    let (content_bytes, content_width) = if sw <= total_width {
        (s.as_bytes(), sw)
    } else {
        // Need to truncate
        let mut acc = 0usize;
        let mut end_bytes = 0usize;
        for (pos, c) in s.char_indices() {
            let cw = char_width(c);
            if acc + cw > total_width {
                end_bytes = pos;
                break;
            }
            acc += cw;
            end_bytes = pos + c.len_utf8();
        }
        (&s.as_bytes()[..end_bytes], acc)
    };

    let remaining = total_width.saturating_sub(content_width);
    let (left_pad, right_pad) = match align {
        Align::Left => (0, remaining),
        Align::Right => (remaining, 0),
        Align::Center => {
            let l = remaining / 2;
            let r = remaining - l;
            (l, r)
        }
    };

    for _ in 0..left_pad {
        out.write_all(fill.as_bytes())?;
    }
    out.write_all(content_bytes)?;
    for _ in 0..right_pad {
        out.write_all(fill.as_bytes())?;
    }
    Ok(())
}
