// Command-line argument parsing.

use crate::style::Style;
use crate::table::Align;

pub struct Args {
    pub file: Option<String>,
    pub no_headers: bool,
    pub number: bool,
    pub tsv: bool,
    pub delimiter: u8,
    pub style: Style,
    pub padding: usize,
    pub indent: usize,
    pub sniff: usize,
    pub header_align: Align,
    pub body_align: Align,
    pub disable_pager: bool,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            file: None,
            no_headers: false,
            number: false,
            tsv: false,
            delimiter: b',',
            style: Style::Sharp,
            padding: 1,
            indent: 0,
            sniff: 1000,
            header_align: Align::Center,
            body_align: Align::Left,
            disable_pager: false,
        }
    }
}

pub enum ParseResult {
    Ok(Args),
    Help(String),
    Version(String),
    Err { message: String, exit_code: i32 },
}

pub const VERSION: &str = "csview 1.3.4";

pub fn help_text() -> String {
    String::from(
"A high performance csv viewer with cjk/emoji support.

Usage: executable [OPTIONS] [FILE]

Arguments:
  [FILE]
          File to view

Options:
  -H, --no-headers
          Specify that the input has no header row

  -n, --number
          Prepend a column of line numbers to the table

  -t, --tsv
          Use '\\t' as delimiter for tsv

  -d, --delimiter <DELIMITER>
          Specify the field delimiter [default: ,]

  -s, --style <STYLE>
          Specify the border style [default: sharp] [possible values: none, ascii, ascii2, sharp,
          rounded, reinforced, markdown, grid]

  -p, --padding <PADDING>
          Specify padding for table cell [default: 1]

  -i, --indent <INDENT>
          Specify global indent for table [default: 0]

      --sniff <LIMIT>
          Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit
          [default: 1000]

      --header-align <HEADER_ALIGN>
          Specify the alignment of the table header [default: center] [possible values: left,
          center, right]

      --body-align <BODY_ALIGN>
          Specify the alignment of the table body [default: left] [possible values: left, center,
          right]

  -P, --disable-pager
          Disable pager

  -h, --help
          Print help

  -V, --version
          Print version
")
}

fn usage() -> String {
    String::from("Usage: executable [OPTIONS] [FILE]")
}

fn tip_more_info() -> String {
    String::from("For more information, try '--help'.")
}

pub fn parse_args<I: Iterator<Item = String>>(mut args: I) -> ParseResult {
    // Skip program name
    let _prog = args.next();
    let mut result = Args::default();
    let mut positional: Option<String> = None;
    let mut only_positional = false;

    // Track which options have been set (to detect multiple uses).
    let mut seen_no_headers = false;
    let mut seen_number = false;
    let mut seen_tsv = false;
    let mut seen_delim = false;
    let mut seen_style = false;
    let mut seen_padding = false;
    let mut seen_indent = false;
    let mut seen_sniff = false;
    let mut seen_header_align = false;
    let mut seen_body_align = false;
    let mut seen_disable_pager = false;

    while let Some(a) = args.next() {
        if only_positional {
            if positional.is_none() {
                positional = Some(a);
            } else {
                return err_unexpected(&a);
            }
            continue;
        }

        if a == "--" {
            only_positional = true;
            continue;
        }

        // Long options
        if a.starts_with("--") {
            let (name, value) = match a.find('=') {
                Some(i) => (a[2..i].to_string(), Some(a[i + 1..].to_string())),
                None => (a[2..].to_string(), None),
            };
            match name.as_str() {
                "help" => return ParseResult::Help(help_text()),
                "version" => return ParseResult::Version(format!("{}\n", VERSION)),
                "no-headers" => {
                    if seen_no_headers {
                        return err_multi("--no-headers");
                    }
                    seen_no_headers = true;
                    result.no_headers = true;
                }
                "number" => {
                    if seen_number {
                        return err_multi("--number");
                    }
                    seen_number = true;
                    result.number = true;
                }
                "tsv" => {
                    if seen_tsv {
                        return err_multi("--tsv");
                    }
                    seen_tsv = true;
                    result.tsv = true;
                    result.delimiter = b'\t';
                }
                "delimiter" => {
                    if seen_delim {
                        return err_multi("--delimiter <DELIMITER>");
                    }
                    seen_delim = true;
                    let v = match take_value(value, &mut args, "--delimiter <DELIMITER>") {
                        Ok(v) => v,
                        Err(e) => return e,
                    };
                    match parse_delimiter(&v) {
                        Ok(d) => result.delimiter = d,
                        Err(msg) => {
                            return err_invalid_value("--delimiter <DELIMITER>", &v, &msg);
                        }
                    }
                }
                "style" => {
                    if seen_style {
                        return err_multi("--style <STYLE>");
                    }
                    seen_style = true;
                    let v = match take_value(value, &mut args, "--style <STYLE>") {
                        Ok(v) => v,
                        Err(e) => return e,
                    };
                    match Style::parse(&v) {
                        Some(st) => result.style = st,
                        None => return err_invalid_style(&v),
                    }
                }
                "padding" => {
                    if seen_padding {
                        return err_multi("--padding <PADDING>");
                    }
                    seen_padding = true;
                    let v = match take_value(value, &mut args, "--padding <PADDING>") {
                        Ok(v) => v,
                        Err(e) => return e,
                    };
                    match v.parse::<usize>() {
                        Ok(n) => result.padding = n,
                        Err(e) => {
                            return err_invalid_value(
                                "--padding <PADDING>",
                                &v,
                                &format!("{}", e),
                            );
                        }
                    }
                }
                "indent" => {
                    if seen_indent {
                        return err_multi("--indent <INDENT>");
                    }
                    seen_indent = true;
                    let v = match take_value(value, &mut args, "--indent <INDENT>") {
                        Ok(v) => v,
                        Err(e) => return e,
                    };
                    match v.parse::<usize>() {
                        Ok(n) => result.indent = n,
                        Err(e) => {
