fn take_value<I: Iterator<Item = String>>(
    inline: Option<String>,
    args: &mut I,
    opt_name: &str,
) -> Result<String, ParseResult> {
    if let Some(v) = inline {
        return Ok(v);
    }
    match args.next() {
        Some(v) => Ok(v),
        None => Err(ParseResult::Err {
            message: format!(
                "error: a value is required for '{}' but none was supplied\n\n{}\n",
                opt_name,
                tip_more_info()
            ),
            exit_code: 2,
        }),
    }
}

fn parse_delimiter(s: &str) -> Result<u8, String> {
    let chars: Vec<char> = s.chars().collect();
    if chars.is_empty() {
        return Err("too few characters in string".to_string());
    }
    if chars.len() != 1 {
        return Err("too many characters in string".to_string());
    }
    let c = chars[0];
    if !c.is_ascii() {
        return Err("non-ascii character".to_string());
    }
    Ok(c as u8)
}

fn err_multi(opt_name: &str) -> ParseResult {
    ParseResult::Err {
        message: format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n\n{}\n",
            opt_name,
            usage(),
            tip_more_info()
        ),
        exit_code: 2,
    }
}

fn err_unexpected(val: &str) -> ParseResult {
    let msg = if val.starts_with("--") || (val.starts_with('-') && val.len() > 1) {
        format!(
            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\n\n{}\n",
            val, val, val, usage(), tip_more_info()
        )
    } else {
        format!(
            "error: unexpected argument '{}' found\n\n{}\n\n{}\n",
            val, usage(), tip_more_info()
        )
    };
    ParseResult::Err { message: msg, exit_code: 2 }
}

fn err_invalid_value(opt_name: &str, val: &str, reason: &str) -> ParseResult {
    ParseResult::Err {
        message: format!(
            "error: invalid value '{}' for '{}': {}\n\n{}\n",
            val, opt_name, reason, tip_more_info()
        ),
        exit_code: 2,
    }
}

fn err_invalid_style(val: &str) -> ParseResult {
    ParseResult::Err {
        message: format!(
            "error: invalid value '{}' for '--style <STYLE>'\n  [possible values: none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid]\n\n{}\n",
