                        Err(e) => return e,
                    };
                    match Align::parse(&v) {
                        Some(a) => result.body_align = a,
                        None => return err_invalid_align("--body-align <BODY_ALIGN>", &v),
                    }
                }
                "disable-pager" => {
                    if seen_disable_pager {
                        return err_multi("--disable-pager");
                    }
                    seen_disable_pager = true;
                    result.disable_pager = true;
                }
                _ => {
                    return err_unexpected(&a);
                }
            }
            continue;
        }

        // Short options
        if a.starts_with('-') && a.len() > 1 && a != "-" {
            let bytes = a.as_bytes();
            let mut i = 1usize;
            while i < bytes.len() {
                let c = bytes[i] as char;
                i += 1;
                match c {
                    'h' => return ParseResult::Help(help_text()),
                    'V' => return ParseResult::Version(format!("{}\n", VERSION)),
                    'H' => {
                        if seen_no_headers {
                            return err_multi("--no-headers");
                        }
                        seen_no_headers = true;
                        result.no_headers = true;
                    }
                    'n' => {
                        if seen_number {
                            return err_multi("--number");
                        }
                        seen_number = true;
                        result.number = true;
                    }
                    't' => {
                        if seen_tsv {
                            return err_multi("--tsv");
                        }
                        seen_tsv = true;
                        result.tsv = true;
                        result.delimiter = b'\t';
                    }
                    'P' => {
                        if seen_disable_pager {
                            return err_multi("--disable-pager");
                        }
                        seen_disable_pager = true;
                        result.disable_pager = true;
                    }
                    'd' | 's' | 'p' | 'i' => {
                        // options with value: take the rest of this arg (skip leading '=') or next arg
                        let v = if i < bytes.len() {
                            let mut s = std::str::from_utf8(&bytes[i..]).unwrap_or("").to_string();
                            if s.starts_with('=') {
                                s.remove(0);
                            }
                            i = bytes.len();
                            s
                        } else {
                            match args.next() {
                                Some(v) => v,
                                None => {
                                    let opt_name = match c {
                                        'd' => "--delimiter <DELIMITER>",
                                        's' => "--style <STYLE>",
                                        'p' => "--padding <PADDING>",
                                        'i' => "--indent <INDENT>",
                                        _ => "",
                                    };
                                    return ParseResult::Err {
                                        message: format!(
                                            "error: a value is required for '{}' but none was supplied\n\n{}\n",
                                            opt_name,
                                            tip_more_info()
                                        ),
                                        exit_code: 2,
                                    };
                                }
                            }
                        };
                        match c {
                            'd' => {
                                if seen_delim {
                                    return err_multi("--delimiter <DELIMITER>");
                                }
                                seen_delim = true;
                                match parse_delimiter(&v) {
                                    Ok(d) => result.delimiter = d,
                                    Err(msg) => {
                                        return err_invalid_value(
                                            "--delimiter <DELIMITER>",
                                            &v,
                                            &msg,
                                        );
                                    }
                                }
                            }
                            's' => {
                                if seen_style {
                                    return err_multi("--style <STYLE>");
                                }
                                seen_style = true;
                                match Style::parse(&v) {
                                    Some(st) => result.style = st,
                                    None => return err_invalid_style(&v),
                                }
                            }
                            'p' => {
                                if seen_padding {
                                    return err_multi("--padding <PADDING>");
                                }
                                seen_padding = true;
                                match v.parse::<usize>() {
                                    Ok(n) => result.padding = n,
                                    Err(e) => {
                                        return err_invalid_value(
                                            "--padding <PADDING>",
                                            &v,
                                            &format!("{}", e),
                                        );
                                    }
                                }
                            }
                            'i' => {
                                if seen_indent {
                                    return err_multi("--indent <INDENT>");
                                }
                                seen_indent = true;
                                match v.parse::<usize>() {
                                    Ok(n) => result.indent = n,
                                    Err(e) => {
                                        return err_invalid_value(
                                            "--indent <INDENT>",
                                            &v,
                                            &format!("{}", e),
                                        );
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                    _ => {
                        let opt = format!("-{}", c);
                        return err_unexpected(&opt);
                    }
                }
            }
            continue;
        }

        // positional
        if positional.is_none() {
            positional = Some(a);
        } else {
            return err_unexpected(&a);
        }
    }

    result.file = positional;
    ParseResult::Ok(result)
}

fn take_value<I: Iterator<Item = String>>(
    inline: Option<String>,
    args: &mut I,
    opt_name: &str,
) -> Result<String, ParseResult> {
    if let Some(v) = inline {
        return Ok(v);
    }
    match args.next() {
        Some(v) => Ok(v),
        None => Err(ParseResult::Err {
            message: format!(
                "error: a value is required for '{}' but none was supplied\n\n{}\n",
                opt_name,
                tip_more_info()
            ),
            exit_code: 2,
        }),
    }
}

fn parse_delimiter(s: &str) -> Result<u8, String> {
    let chars: Vec<char> = s.chars().collect();
    if chars.is_empty() {
        return Err("too few characters in string".to_string());
    }
    if chars.len() != 1 {
        return Err("too many characters in string".to_string());
    }
    let c = chars[0];
    if !c.is_ascii() {
        return Err("non-ascii character".to_string());
    }
    Ok(c as u8)
}

fn err_multi(opt_name: &str) -> ParseResult {
    ParseResult::Err {
        message: format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n\n{}\n",
            opt_name,
            usage(),
            tip_more_info()
        ),
        exit_code: 2,
    }
}

fn err_unexpected(val: &str) -> ParseResult {
    let msg = if val.starts_with("--") || (val.starts_with('-') && val.len() > 1) {
        format!(
            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\n\n{}\n",
            val, val, val, usage(), tip_more_info()
        )
    } else {
        format!(
            "error: unexpected argument '{}' found\n\n{}\n\n{}\n",
            val, usage(), tip_more_info()
        )
    };
    ParseResult::Err { message: msg, exit_code: 2 }
}

fn err_invalid_value(opt_name: &str, val: &str, reason: &str) -> ParseResult {
    ParseResult::Err {
        message: format!(
            "error: invalid value '{}' for '{}': {}\n\n{}\n",
            val, opt_name, reason, tip_more_info()
        ),
        exit_code: 2,
    }
}

fn err_invalid_style(val: &str) -> ParseResult {
    ParseResult::Err {
        message: format!(
            "error: invalid value '{}' for '--style <STYLE>'\n  [possible values: none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid]\n\n{}\n",
            val, tip_more_info()
        ),
        exit_code: 2,
    }
}

fn err_invalid_align(opt_name: &str, val: &str) -> ParseResult {
    ParseResult::Err {
        message: format!(
            "error: invalid value '{}' for '{}'\n  [possible values: left, center, right]\n\n{}\n",
            val, opt_name, tip_more_info()
        ),
        exit_code: 2,
    }
}
