use crate::csv_parse::{CsvError, CsvReader};
use crate::table::{Table, TableOptions};

fn main() {
    let argv: Vec<String> = env::args().collect();
    let parsed = parse_args(argv.into_iter());
    match parsed {
        ParseResult::Help(s) => {
            print!("{}", s);
            std::process::exit(0);
        }
        ParseResult::Version(s) => {
            print!("{}", s);
            std::process::exit(0);
        }
        ParseResult::Err { message, exit_code } => {
            eprint!("{}", message);
            std::process::exit(exit_code);
        }
        ParseResult::Ok(a) => match run(a) {
            Ok(()) => std::process::exit(0),
            Err(e) => {
                eprintln!("csview: {}", e);
                std::process::exit(1);
            }
        },
    }
}

enum AppError {
    Io(io::Error),
    Csv(CsvError),
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AppError::Io(e) => write!(f, "{} (os error {})", e, e.raw_os_error().unwrap_or(0)),
            AppError::Csv(e) => write!(f, "{}", e),
        }
    }
}

fn run(args: Args) -> Result<(), AppError> {
    // Read input
    let input: Box<dyn Read> = match &args.file {
        Some(path) => {
            let f = File::open(path).map_err(AppError::Io)?;
            Box::new(BufReader::new(f))
        }
        None => Box::new(io::stdin()),
    };

    // Parse CSV into rows of strings.
    let mut reader = CsvReader::new(input, args.delimiter);
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut expected_fields: Option<usize> = None;
    let mut record_no: u64 = 0;
    loop {
        let rec_start_byte = reader.byte_pos;
        let rec_start_line = reader.line;
        match reader.next_record() {
            Err(CsvError::Io(e)) => return Err(AppError::Io(e)),
            Err(e) => return Err(AppError::Csv(e)),
            Ok(None) => break,
            Ok(Some(fields)) => {
                // Convert to strings, validating UTF-8
                let mut row: Vec<String> = Vec::with_capacity(fields.len());
                for (idx, f) in fields.iter().enumerate() {
                    match std::str::from_utf8(f) {
                        Ok(s) => row.push(s.to_string()),
                        Err(_) => {
                            return Err(AppError::Csv(CsvError::Utf8 {
                                record: record_no,
                                line: rec_start_line,
                                field: idx as u64,
                                byte: rec_start_byte + 1,
                            }));
                        }
                    }
                }
                // Check column count consistency
                if let Some(n) = expected_fields {
                    if row.len() != n {
                        return Err(AppError::Csv(CsvError::BadRecord {
                            record: record_no,
                            line: rec_start_line,
                            byte: rec_start_byte + 1,
                            got: row.len(),
                            want: n,
                        }));
                    }
                } else {
                    expected_fields = Some(row.len());
                }
                records.push(row);
                record_no += 1;
            }
        }
    }

    // Determine header and rows.
    let (header, mut rows) = if args.no_headers {
        (None, records)
    } else if records.is_empty() {
        (None, records)
    } else {
        let hdr = records.remove(0);
        (Some(hdr), records)
    };

    // Apply --number prepending.
    let (header, rows) = if args.number {
        let mut new_header = None;
        if let Some(h) = header {
            let mut nh = Vec::with_capacity(h.len() + 1);
            nh.push("#".to_string());
            nh.extend(h);
            new_header = Some(nh);
        }
        let mut new_rows: Vec<Vec<String>> = Vec::with_capacity(rows.len());
        for (i, r) in rows.into_iter().enumerate() {
            let mut nr = Vec::with_capacity(r.len() + 1);
            nr.push((i + 1).to_string());
            nr.extend(r);
            new_rows.push(nr);
        }
        (new_header, new_rows)
    } else {
        (header, rows)
    };

    let opts = TableOptions {
        style: args.style,
        padding: args.padding,
        indent: args.indent,
        header_align: args.header_align,
        body_align: args.body_align,
        sniff_limit: args.sniff,
    };

    let table = Table {
        header,
        rows,
        opts,
    };

    // Decide about pager.
    let use_pager = !args.disable_pager && is_stdout_tty();

    if use_pager {
        // Try spawning less (with -FRX flags similar to csview defaults)
        let mut cmd = Command::new("less");
        cmd.env("LESSCHARSET", "utf-8");
