fn jaro(s1: &[char], s2: &[char]) -> f64 {
    if s1 == s2 {
        return 1.0;
    }
    let l1 = s1.len();
    let l2 = s2.len();
    if l1 == 0 || l2 == 0 {
        return 0.0;
    }
    let match_distance = if std::cmp::max(l1, l2) / 2 == 0 { 0 } else { std::cmp::max(l1, l2) / 2 - 1 };
    let mut s1_matches = vec![false; l1];
    let mut s2_matches = vec![false; l2];
    let mut matches: usize = 0;
    for i in 0..l1 {
        let start = i.saturating_sub(match_distance);
        let end = std::cmp::min(i + match_distance + 1, l2);
        for j in start..end {
            if s2_matches[j] { continue; }
            if s1[i] != s2[j] { continue; }
            s1_matches[i] = true;
            s2_matches[j] = true;
            matches += 1;
            break;
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions: usize = 0;
    let mut k: usize = 0;
    for i in 0..l1 {
        if !s1_matches[i] { continue; }
        while !s2_matches[k] { k += 1; }
        if s1[i] != s2[k] { transpositions += 1; }
        k += 1;
    }
    let t = (transpositions / 2) as f64;
    let m = matches as f64;
    (m / l1 as f64 + m / l2 as f64 + (m - t) / m) / 3.0
}

fn suggest_best<'a>(input: &str, choices: &[&'a str]) -> Option<&'a str> {
    let input_chars: Vec<char> = input.chars().collect();
    let mut best: Option<(f64, &str)> = None;
    for c in choices {
        let cc: Vec<char> = c.chars().collect();
        let s = jaro(&input_chars, &cc);
        match best {
            None => best = Some((s, *c)),
            Some((bs, _)) if s > bs => best = Some((s, *c)),
            _ => {}
        }
    }
